pub struct Literal {
    pub name: &'static str,
    pub hex: &'static str,
    pub operation: u8,
    pub epoch: u64,
    pub target: bool,
    pub role: u8,
    pub recipient: u128,
    pub origin_account: u128,
    pub grant_expiry: i128,
    pub bvalid: bool,
    pub cvalid: bool,
    pub fields: &'static [(&'static str, usize, usize)],
}
impl Literal {
    pub fn at(&self, name: &str) -> usize {
        self.fields.iter().find(|x| x.0 == name).unwrap().1
    }
    pub fn bytes(&self) -> Vec<u8> {
        assert_eq!(self.hex.len() % 2, 0);
        self.hex
            .as_bytes()
            .chunks_exact(2)
            .map(|x| {
                let s = std::str::from_utf8(x).unwrap();
                u8::from_str_radix(s, 16).unwrap()
            })
            .collect()
    }
}
